parameterdescription.para:
keyの長さを生成します。ED25519の場合は常に32になります。 Example intret;

WC_RNGrng;
ed25519_keykey;

wc_InitRng(&rng);
wc_ed25519_init(&key);
wc_ed25519_make_key(&rng,32,&key);
if(ret!=0){
//errormakingkey
}

simplesect.para:
BAD_FUNC_ARGS 与えられたキーがNULLの場合に返されます。 Example intret;
bytepriv[]={initializewith57byteprivatekey};
bytepub[]={initializewiththecorrespondingpublickey};

ed25519_keykey;
wc_ed25519_init_key(&key);
wc_ed25519_import_private_key(priv,sizeof(priv),pub,sizeof(pub),&key);
ret=wc_ed25519_check_key(&key);
if(ret!=0){
//errorcheckingkey
}

BAD_FUNC_ARGS 与えられたキーがNULLの場合に返されます。 Example intkeySz;
ed25519_keykey;
//initializekey,makekey
keySz=wc_ed25519_size(&key);
if(keySz==0){
//errordeterminingkeysize
}

BAD_FUNC_ARG key引数がnullの場合に返されます。 Example ed25519_keykey;
wc_ed25519_init(&key);

WC_RNGrng;
wc_InitRng(&rng);

wc_ed25519_make_key(&rng,32,&key);//initialize32byteEd25519key
intkey_size=wc_ed25519_priv_size(&key);

BAD_FUNC_ARG key引数がnullの場合は返します。 Example ed25519_keykey;
wc_ed25519_init(&key);
WC_RNGrng;
wc_InitRng(&rng);

wc_ed25519_make_key(&rng,32,&key);//initialize32byteEd25519key
intkey_size=wc_ed25519_pub_size(&key);

BAD_FUNC_ARG key引数がnullの場合は返します。 Example intsigSz;
ed25519_keykey;
//initializekey,makekey

sigSz=wc_ed25519_sig_size(&key);
if(sigSz==0){
//errordeterminingsigsize
}
